head.script:
scwin.makeDataList = function(id, obj) {
	$p.data.create({
		"id": id,
		"type": "dataList",
		"option": {
			"useData": false
		},
		"columnInfo": obj
	});
};
scwin.onpageload = function() {
	var jsonData = [{
			"value": "a",
			"label": "test1"
		},
		{
			"value": "b",
			"label": "test2"
		},
		{
			"value": "c",
			"label": "test3"
		}
	];
	var column = {};
	var columnArr = [];
	for (var k in jsonData[0]) {
		column = {};
		column["id"] = k;
		column["dataType"] = "text";
		columnArr.push(column);
	}
	scwin.makeDataList("dataList1", columnArr);
	dataList1.setJSON(jsonData);
	dataList2.setJSON(jsonData);
};
